/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;import page2020.view.Tag;public class H5meter extends Tag<H5meter> {	public static final class Attr {		public static final String form = "form";		public static final String high = "high";		public static final String low = "low";		public static final String max = "max";		public static final String min = "min";		public static final String optimum = "optimum";		public static final String value = "value";	}	private static Logger log = LoggerFactory.getLogger(H5meter.class);	public H5meter() {		super("meter");	}	public H5meter form(String id) {		if (EmptyUtil.not(id)) {			super.getAttrMap().put(Attr.form, id.trim());		} else {			log.error("form: argument(id) is empty !");		}		return this;	}	public H5meter high(double number) {		if (number > 0) {			super.getAttrMap().put(Attr.high, Double.valueOf(number));		} else {			log.error("high: argument(number) should be more then zero !");		}		return this;	}	public H5meter low(double number) {		if (number >= 0) {			super.getAttrMap().put(Attr.low, Double.valueOf(number));		} else {			log.error("low: argument(number) is negative !");		}		return this;	}	public H5meter max(double number) {		if (number > 0) {			super.getAttrMap().put(Attr.max, Double.valueOf(number));		} else {			log.error("max: argument(number) should be more then zero !");		}		return this;	}	public H5meter min(double number) {		if (number >= 0) {			super.getAttrMap().put(Attr.min, Double.valueOf(number));		} else {			log.error("min: argument(number) is less then 0 !");		}		return this;	}	public H5meter optimum(double number) {		if (number >= 0) {			super.getAttrMap().put(Attr.optimum, Double.valueOf(number));		} else {			log.error("optimum: argument(number) is less then 0 !");		}		return this;	}	public H5meter value(double number) {		if (number >= 0) {			super.getAttrMap().put(Attr.value, Double.valueOf(number));		} else {			log.error("value: argument(number) is less then 0 !");		}				return this;	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.form:		case Attr.high:		case Attr.low:		case Attr.max:		case Attr.min:		case Attr.optimum:		case Attr.value:			return true;		default:			return super.isAttr(attrName);		}	}}